import './App.css';
import User from './user.js';

import panda from './images/panda.png';
import hacker from './images/hacker.png';
import pikachu from './images/pikachu.png';

import User_feedback from './ser_feedback.js';


function App() {      
  return (
    <div className="App">
      <h1 style={{textAlign: 'center'}}>Joseph Evans</h1>

      <main className='container'>
        {/* <User 1 /> */}
      <User_feedback username="Pikachu">
        <User image={pikachu} username="Pikachu" date="10/12/2023" msg="Pikachu!!!" />
      </User_feedback>

        {/*' <User 2 /> */}
      <User_feedback username="Panda"> 
          <User image={panda} username="Panda" date="10/10/2023" msg="Bepo, Heart Pirates!!." />
      </User_feedback>

       {/* <User 3 /> */}
      <User_feedback username="Hacker"> 
          <User image={hacker} username="Hacker" date="10/11/2023" msg="White Hat" />
      </User_feedback>
        </main> 
    </div>
  );

}

export default App;
